"""Assemble C.1 reports exclusively from observed security and regression evidence."""
from pathlib import Path
import json,hashlib,re,xml.etree.ElementTree as ET
from datetime import datetime,timezone
R=Path('reports');ROOT=Path.cwd()
def read(name):return json.loads((R/name).read_text(encoding='utf-8-sig'))
def write(name,data):(R/name).write_text(json.dumps(data,indent=2,default=str),encoding='utf8')
matrix=read('search_v2c_c1_matrix_observed.json');assert len(matrix)==20
summary={k:{i:v for i,v in row.items() if i not in ['before','after']} for k,row in matrix.items()}
write('search_v2c_c1_authorization_matrix.json',{'result':'PASS','cases':matrix,'source':'20 isolated real Mongo tests; full before/after accepted, pending and profile state included.'})
def group(name,cases,note):write('search_v2c_c1_'+name+'.json',{'result':'PASS','explanation':note,'cases':{k:summary[k] for k in cases},'complete_state_evidence':'search_v2c_c1_authorization_matrix.json'})
group('workspace_isolation',['patron_staff','staff_patron','foreign_choice','workspace_switch','missing_library','recovery_not_revocation'],'A denied requested workspace never proves another authorized workspace inaccessible. Recovery503 and ordinary endpoint errors have no destructive effect.')
group('invalidation_scope',['revocation','role_upgrade','role_downgrade','account_disabled','logout'],'Accepted and pending deletion uses exact user_id/login_session/scope/library_id/workspace. Only explicit logout retains existing account-wide cleanup. Account disable is checked fresh; unrelated retained state cannot be accessed while disabled.')
group('pending_clarification_isolation',['patron_staff','staff_patron','foreign_choice','sid_denied','global_malformed','revocation'],'Pending rows use the same ownership predicate as accepted contexts; legitimate lifecycle consumption remains independent.')
group('personalization_isolation',list(matrix),'Exact cache prefix (user_id,sid,library_id,staff). Sentinel profiles prove deletion boundaries; ordinary personalization policy remains off by default and own Reading List only.')
group('multi_library',['library_denied','revocation','interleaved_revocation'],'Library A loss leaves authorized library B unchanged. Unknown/denied B request leaves valid A unchanged. Logical A/B labels are symmetric; no tenant transfer.')
group('sid_isolation',['sid_denied','foreign_user_denied','revocation','account_disabled','logout'],'Denial/cleanup affects only current JWT sid; other sids receive fresh canonical checks on their own requests. Explicit logout preserves existing account-wide behavior.')
group('role_transition',['role_upgrade','role_downgrade','staff_patron','interleaved_role_change'],'Existing GENERAL_USER patron versus ADMIN/LIBRARIAN staff policy unchanged. Only inaccessible former workspace is removed; new authorized workspace survives.')
group('concurrency',[k for k in matrix if k.startswith('interleaved_')],'Five deterministic interleavings: valid Search, resolution, revocation, role change, logout. Existing lock and CAS/receipt behavior prevent rollback, unrelated deletion, resurrection, stale overwrite.')
live=read('search_v2c_c1_live_postpatch.json');assert live['status']==403 and all(live[k] for k in ['accepted_unchanged','pending_unchanged','global_unchanged','other_library_unchanged'])
browser_public=read('search_v2c_c1_browser_public_mongo.json');browser_private=read('search_v2c_c1_browser_private_mongo.json');rev=read('search_v2c_c1_browser_revocation_mongo.json')
for d in [browser_public,browser_private]:assert d['http_status']==403 and d['accepted_unchanged'] and d['pending_unchanged'] and d['exactly_one_commit']
assert rev['scope_exact'] and rev['unrelated_preserved']
write('search_v2c_c1_revocation.json',{'result':'PASS','isolated_cases':{k:summary[k] for k in ['revocation','account_disabled','interleaved_revocation']},'live_browser_mongo':rev,'denial_server_log':'search_v2c_c1_server.stdout.log: q=neura private staff=false returned404','timing':'search_v2c_c1_revocation_measurements.json','note':'Measured before logout. Global and public accepted/pending records match byte-equivalent serialized documents. Disposable QA membership later restored for repeat private capture, then removed and archived by final cleanup.'})
suites={}
for name in ['parser','tenant','catalogue','retrieval','inventory']:
 root=ET.parse(R/('search_v2c_c1_'+name+'.xml')).getroot();cases=root.findall('.//testcase');errors=len(root.findall('.//error'));failures=len(root.findall('.//failure'));assert errors==failures==0
 suites[name]={'tests':len(cases),'failures':failures,'errors':errors,'xml':'search_v2c_c1_'+name+'.xml','cases':[x.attrib['classname']+'::'+x.attrib['name'] for x in cases]}
total=sum(s['tests'] for s in suites.values());assert total==1803
write('search_v2c_c1_backend_regression.json',{'result':'PASS','total':total,'suites':suites,'counting':'Disjoint suite totals only. Focused matrix/lifecycle reruns are subsets and not added. Initial full tenant run had one snapshot helper error before assertions; immutable vocabulary snapshot fixed and entire278-case suite rerun successfully. No security assertion removed. Inventory95 isolated cases additionally run.'})
b1=[x for x in suites['tenant']['cases'] if 'test_query_v2c_b1::' in x or 'test_query_v2c_b_stop_condition::' in x];assert len(b1)==18
write('search_v2c_c1_v2cb1_regression.json',{'result':'PASS','cases':b1,'count':18,'v2cb_interactions_count':49,'source':'search_v2c_c1_tenant.xml','guarantees':{k:'PASS' for k in ['forged_choice_state_unchanged','valid_after_forged','expiry','cross_clarification','cross_user','cross_sid','cross_library','cross_workspace','duplicate','stale_operations','membership_revocation','backend_validated_chip_edits']},'raw_forged_choice':'search_v2c_b1_forged_choice.json','retained_reproducer':'search_v2c_b1_retained_reproducer.json','note':'Frozen lifecycle behavior retained. Test-only recursive cache snapshot supports immutable vocabulary projections in complete-suite order.'})
log=(R/'search_v2c_c1_frontend_full.log').read_text(encoding='utf8',errors='replace');counts=[int(x) for x in re.findall(r'ℹ tests (\d+)',log)];fails=[int(x) for x in re.findall(r'ℹ fail (\d+)',log)];assert len(counts)==30 and sum(counts)==903 and len(fails)==30 and not any(fails)
assert 'built in' in (R/'search_v2c_c1_build.log').read_text(encoding='utf8',errors='replace')
write('search_v2c_c1_frontend_regression.json',{'result':'PASS','full_suite_tests':903,'groups':30,'failures':0,'typescript':'PASS','production_build':'PASS','sources':['search_v2c_c1_frontend_full.log','search_v2c_c1_typescript.log','search_v2c_c1_build.log'],'warnings':'Existing bundle-size/dynamic-import warnings; no frontend application changes.'})
observations=read('search_v2c_c1_browser_observations.json');names={o['name'] for o in observations}
for required in ['private outsider no content','private staff authorized autocomplete','public TEST staff authorized autocomplete','actual membership revocation clears private content','final restored Global catalogue']:assert required in names,required
write('search_v2c_c1_browser.json',{'result':'PASS','browser':'Real Chromium, Codex in-app browser, http://127.0.0.1:5174','required_contexts':['Global','public TEST patron','public TEST staff','private patron','private staff','private outsider'],'public_denial_and_valid_resolution':browser_public,'private_denial_and_valid_resolution':browser_private,'membership_revocation':'search_v2c_c1_browser_revocation_mongo.json','outsider_api':read('search_v2c_c1_outsider_api.json'),'observations':'search_v2c_c1_browser_observations.json','screenshot':'search_v2c_c1_final_browser.png','process':read('search_v2c_c1_process.json'),'running_service':read('search_v2c_c1_running_service.json'),'fixture_cleanup':read('search_v2c_c1_fixture.json'),'note':'Private Mongo denial/resolution capture repeated after a report filename collision was corrected. First flow and revocation UI observations retained. Cross-workspace request used live API with the actual browser-created context owner and JWT sid; UI performed searches and legitimate resolutions. No browser token or credentials saved.'})
before=read('search_v2c_c1_before_measurements.json');after=read('search_v2c_c1_after_measurements.json');revtime=read('search_v2c_c1_revocation_measurements.json')
write('search_v2c_c1_performance.json',{'result':'MEASURED','before':before,'after':after,'real_revocation_invalidation':revtime,'method':'50 sequential samples per operation against same authoritative private QA tenant. Direct authorization measures existing canonical dependency; denied workspace/search/resolution use HTTP running service.30 fresh real canonical revocations measured direct helper. Idle browser during samples; broad regressions completed before after samples. No speedup claim.','interpretation':'Authorization p50 changed20.988→21.433ms; denied workspace17.599→27.830ms from extra canonical classification on failure; ordinary valid Search118.869→120.833ms. Resolution122.848→147.186ms (p95 152.231→167.259); observed increase disclosed, single before/after series does not establish cause. Parser and successful authorization algorithms unchanged. No gross ordinary Search regression observed.','fixture_capacity_note':'Initial timing run accumulated QA contexts and exercised existing account32-context capacity eviction. Browser isolation flows were captured before timing; fresh Global/public/private contexts were explicitly created afterward for revocation proof. Timing script now deletes each iteration outside measured interval to avoid future QA capacity interference.'})
baseline=read('search_v2c_c1_baseline.json')['files'];files=[];changed=[]
allowed_sources={'search/interaction_api.py','search/session_store.py','search/scope_authorization.py','search/personalization.py','search/query_execution.py','tests/institution_v2g/test_query_v2c_b1.py','tests/institution_v2g/test_query_v2c_c.py'}
allowed_reports={'reports/search_v2c_b1_forged_choice.json','reports/search_v2c_b1_retained_reproducer.json','reports/search_v2c_b1_server_final.stdout.log','reports/search_v2c_c_preflight_security.json'}
for n,v in baseline.items():
 p=Path(n);assert p.exists(),n;st=p.stat();now={'size':st.st_size,'mtime_ns':st.st_mtime_ns}
 if 'sha256' in v:now['sha256']=hashlib.sha256(p.read_bytes()).hexdigest();same=now['sha256']==v['sha256'];method='SHA256'
 else:same=now==v;method='size and nanosecond mtime (large artifact; no full hash)'
 rel=p.relative_to(ROOT).as_posix();files.append({'file':rel,'before':v,'after':now,'unchanged':same,'method':method})
 if not same:changed.append(rel);assert rel in allowed_sources|allowed_reports,rel
drafts=[x for x in files if x['file'].startswith('reports/search_v2c_c_gold_') or x['file'] in ['reports/search_v2c_c_authored_families.json','reports/search_v2c_c_holdout_manifest.json','scripts/search_v2c_c_author_gold.py']];assert len(drafts)==5 and all(x['unchanged'] for x in drafts)
service=read('search_v2c_c1_running_service.json');assert service['global_book_count']==5000000
write('search_v2c_c1_preservation.json',{'result':'PASS','global_books':5000000,'files':files,'changed_baseline_files':changed,'allowed_difference_explanation':'Five scoped application files and B1 cache snapshot plumbing changed; B1 raw evidence regenerated by regressions; prior running-service stdout appended before old process stopped. C preflight report intentionally refreshed. Original C security/finalQA and gold drafts unchanged.','draft':{'rows':540,'unique_query_texts':530,'families':54,'development':320,'calibration':110,'heldout':110,'AI_reviewed':0,'human_reviewed':0,'status':'UNACCEPTED DRAFT; same bytes as prepatch','hashes':drafts,'heldout_evaluation':False,'parser_tuning':False,'calibration_run':False,'LLM_second_opinion':False},'models_indexes':'All captured global/tenant artifacts and protected model/parser/recommendation/MLT/inventory sources unchanged; large artifacts verified by size/mtime as recorded. No rebuild or migration.'})
new_sources=['tests/institution_v2g/test_query_v2c_c1.py','scripts/search_v2c_c1_fixture.py','scripts/search_v2c_c1_live.py','scripts/search_v2c_c1_browser_state.py','scripts/search_v2c_c1_revocation_timing.py','scripts/search_v2c_c1_outsider.py','scripts/search_v2c_c1_reports.py']
write('search_v2c_c1_changed_files.json',{'application_changes':sorted(x for x in allowed_sources if x.startswith('search/')),'test_plumbing':sorted(x for x in allowed_sources if x.startswith('tests/')),'new_test_and_evidence_sources':new_sources,'evidence_reports':sorted(p.name for p in R.glob('search_v2c_c1_*')),'other_evidence_updated':sorted(allowed_reports),'current_hashes':{n:hashlib.sha256(Path(n).read_bytes()).hexdigest() for n in sorted(allowed_sources|set(new_sources))},'git':'No staging, commit, reset or blanket cleanup. Existing dirty workspace preserved.'})
qa={'FINAL':'PASS','V2C_C1_IMPLEMENTED':'YES','ROOT_CAUSE_CONFIRMED':'YES','CROSS_WORKSPACE_403':'PASS','CROSS_WORKSPACE_MUTATED_ACCEPTED_CONTEXT':'NO','CROSS_WORKSPACE_MUTATED_PENDING_CLARIFICATION':'NO'}
for k in ['WORKSPACE_INVALIDATION_SCOPE_EXACT','PATRON_TO_STAFF_DENIAL_STATE_SAFE','STAFF_TO_PATRON_DENIAL_STATE_SAFE','MULTI_LIBRARY_ISOLATION','JWT_SID_ISOLATION','GLOBAL_TENANT_STATE_ISOLATION','PERSONALIZATION_INVALIDATION_SCOPE','REAL_MEMBERSHIP_REVOCATION_STILL_INVALIDATES','ROLE_TRANSITION_INVALIDATION','CONCURRENT_WORKSPACE_OPERATIONS_SAFE','V2C_B1_FORGED_CHOICE_REGRESSION','V2C_B1_VALID_AFTER_FORGED','V2C_B1_EXPIRY_REGRESSION','V2C_B1_CROSS_USER','V2C_B1_CROSS_SID','V2C_B1_CROSS_LIBRARY','V2C_B1_CROSS_WORKSPACE','V2C_B1_DUPLICATE_CHOICE','V2C_B1_CHIP_EDITING','PRIVATE_OUTSIDER_DENIAL']:qa[k]='PASS'
qa.update(PRIVATE_DATA_LEAKS=0,BACKEND_REGRESSION='1803 passed: parser1307 + tenant278 + catalogue88 + retrieval35 + inventory95; no duplicate subset totals',FRONTEND_FULL_SUITE='903 passed in30 groups;0 failures',TYPESCRIPT='PASS',PRODUCTION_BUILD='PASS',BROWSER_ACCEPTANCE='PASS')
for name,key in [('authorization','AUTHORIZATION_P50_P95'),('denied_workspace','DENIED_WORKSPACE_P50_P95'),('clarification_resolution','CLARIFICATION_RESOLUTION_P50_P95')]:qa[key]={'unit':'ms','n':after[name]['n'],'p50':after[name]['p50_ms'],'p95':after[name]['p95_ms']}
qa.update(GLOBAL_BOOK_COUNT=5000000,GLOBAL_SEARCH_HEALTH='STALE / degraded; HTTP200; baseline_verified=false')
for k in ['V2C_C_DRAFT_ROWS_PRESERVED','V2C_C_UNIQUE_QUERY_TEXTS_PRESERVED','V2C_C_QUERY_FAMILIES_PRESERVED','V2C_C_DEV_CAL_HOLDOUT_PRESERVED','V2C_C_HOLDOUT_HASHES_UNCHANGED']:qa[k]='YES'
for k in ['V2C_C_HELDOUT_EVALUATION_RUN','V2C_C_PARSER_TUNING_RUN','V2C_C_CALIBRATION_RUN','V2C_C_LLM_SECOND_OPINION_STARTED','GLOBAL_HNSW_REBUILT','GLOBAL_KG_REBUILT','TENANT_HNSW_KG_REBUILT','QWEN_CHANGED','RECOMMENDATION_CHANGED','MORE_LIKE_THIS_CHANGED','STAFF_INVENTORY_CHANGED','PART_2I_STARTED']:qa[k]='NO'
write('search_v2c_c1_final_qa.json',qa)
write('search_v2c_c_preflight_security.json',{'observed_at':datetime.now(timezone.utc).isoformat(),'status':'PASS: C.1 targeted security corrective preflight; V2C-C remains PARTIAL and requires its own complete preflight','prior_failure_preserved':'search_v2c_c1_original_preflight_security.json','prepatch_reproducer':'search_v2c_c1_prepatch_reproducer.json','postpatch_live':live,'browser_public':'search_v2c_c1_browser_public_mongo.json','browser_private':'search_v2c_c1_browser_private_mongo.json','revocation':'search_v2c_c1_browser_revocation_mongo.json','matrix':'search_v2c_c1_authorization_matrix.json','concurrency':'search_v2c_c1_concurrency.json','b1_regression':'search_v2c_c1_v2cb1_regression.json','V2C_C_status':'PARTIAL; benchmark paused; no heldout evaluation/calibration/tuning'})
(R/'search_v2c_c1_review.md').write_text('''# V2C-C.1 review

PASS for this corrective patch only. Root cause reproduced before editing, both in isolated Mongo and on the authoritative live service. Five application files change only canonical authorization-loss classification and exact ownership cleanup. Existing logout policy, role boundaries and B1 CAS/claim lifecycle remain intact.

Twenty matrix/interleaving cases pass. Real Chromium public/private patron denial→valid-resolution flows and actual membership revocation are correlated with complete Mongo snapshots. Staff public/private search and suggestions work. Outsider API and UI deny access without observed private content. The repeated private capture corrects evidence-file routing; no application workaround was used. Disposable users494/495 are disabled, their memberships removed and private QA library archived. Normal Test User Global catalogue restored.

1803 disjoint backend tests and903 frontend tests pass; TypeScript/build pass. Inventory95 cases and catalogue staff/recommendation tests are included. Broad first tenant attempt exposed only immutable vocabulary test-copy plumbing; the complete suite was rerun successfully after correcting it. Model/index preservation uses SHA256 for smaller captured files and size/mtime for large files; this is not a new full9GB index integrity certification. Global health stays STALE/degraded, baseline_verified=false.

Timing is reported without a speedup claim. Denial gets fresh canonical proof and therefore costs more; ordinary Search p50 is118.869→120.833ms. Clarification resolution p50 rises122.848→147.186ms in the observed50-sample series; this difference is disclosed rather than attributed conclusively. Fresh revocation cleanup p50/p95 is16.582/24.938ms over30 repetitions. Initial timing-context accumulation exercised normal QA account capacity eviction; browser revocation used freshly recreated accepted scopes, and the timing script now cleans each iteration outside timing.

The540/530/54 draft population,320/110/110 split, original holdout manifest retain exact baseline hashes; the authoring source was not edited. AI-reviewed0; human-reviewed0. No C heldout evaluation, parser tuning, confidence calibration, optional LLM or Part2I. Original C finalQA remains PARTIAL. This is a primary-agent review; no additional independent reviewer was commissioned for C.1.

All18 requested C.1 gates pass on their scoped evidence. C security preflight may now be rerun separately; do not infer full V2C-C acceptance or resume benchmark work automatically.
''',encoding='utf8')
print(json.dumps({'result':'PASS','backend':total,'frontend':903,'baseline_files':len(files),'draft_hashes_unchanged':len(drafts)}))



